/// <summary>
/// Update METLineCount and rest Integration status if the counting journal is valid
/// </summary>
/// <param name = "_inventJournalTable">inventJournalTable</param>
public static void updateMETLineCountAndResetIntStatusIfvalidCountingJournal(InventJournalTable _inventJournalTable)
{
    if (_inventJournalTable)
    {
        InventJournalTrans inventJournalTrans;

        select count(RecId) from inventJournalTrans
            where inventJournalTrans.JournalId == _inventJournalTable.JournalId;

        if (inventJournalTrans.RecId > 0 
            && (inventJournalTrans.RecId != _inventJournalTable.METJournalLinesCount
                || _inventJournalTable.METIntegrationStatus == METIntegrationStatus::Error))
        {
            ttsbegin;
            _inventJournalTable.selectForUpdate(true);
            _inventJournalTable.skipDataMethods(true);
            _inventJournalTable.skipBusinessEvents(true);
            _inventJournalTable.skipDataSourceValidateWrite(true);
            _inventJournalTable.skipEvents(true);

            _inventJournalTable.METJournalLinesCount = inventJournalTrans.RecId;
            _inventJournalTable.METIntegrationStatus = METIntegrationStatus::None;
            _inventJournalTable.update();
            ttscommit;
        }
    }
}
